/**
 * Loads one installed package or path: its pi-durable extension when it declares one (`pi.durable`), else its pi
 * extensions, for their providers.
 */
async function loadRoot(
	root: { name: string; path: string },
	jiti: ReturnType<typeof createJiti>,
	loaded: LoadedExtensions,
	log: ExtensionLog,
	cwd: string,
): Promise<void> {
	const durable = findDurableEntry(root.path);
	if (durable !== undefined) {
		if ((readPiExtensions(root.path) ?? []).length > 0) {
			log.info(
				`${root.name} has a pi-durable extension (pi.durable) and pi extensions (pi.extensions); loading only the pi-durable one, as the others need pi's coding agent`,
			);
		}
		const shown = displayPath(durable, cwd);
		loaded.durable.push(await loadDurableEntry(durable, jiti, shown));
		log.info(`Loaded pi-durable extension ${shown}`);
		return;
	}
	const entries = findExtensionEntries(root.path);
	if (entries.length === 0) {
	options: DurableExtensionsOptions,
): Promise<Extension[]> {
	if (factories.length === 0) {
		return [];
	}
	const { cwd, trustProject, ui, log } = options;
	const agentDir = await agentDirectory(options);
	log.info(
		`pi-durable extensions: agent directory ${agentDir}, project ${trustProject ? "trusted" : "not trusted"}, ${ui ? "questions answered on GitHub" : "no UI"}`,
	);
	const names = new Set([CodingTools.name]);
	const extensions: Extension[] = [];
	for (const factory of factories) {
		let extension: Extension;
		try {
			// oxlint-disable-next-line eslint/no-await-in-loop -- extensions are created in order, as they were loaded
			extension = await factory.create({
				cwd,
				agentDir,
				trustProject,
				...(ui ? { ui } : {}),
				log: { info: log.info, warning: log.warning },
			});
		} catch (error) {
			throw new Error(
				`Could not create pi-durable extension ${factory.source}: ${getErrorMessage(error)}`,
				{ cause: error },
			);
		}
		if (names.has(extension.name)) {
			throw new Error(
				`pi-durable extension ${factory.source} is named "${extension.name}", which is already taken`,
			);
		}
		names.add(extension.name);
		log.info(
			`pi-durable extension ${extension.name} (${factory.source}): ${(extension.tools ?? []).map((tool) => tool.name).join(", ") || "no tools"}`,
		);
		extensions.push(extension);
	}
	return extensions;
}
